export const rightsCashDefinitions={rightsCash:{title:'Separate theoretical rights value from the cash required to subscribe',fields:[
 ['rightsUnits','Existing eligible shares in the hypothetical holding',100,0,1000,10],
 ['rightsOldPrice','Hypothetical price before rights detach (CAD per share)',10,0,100,1],
 ['rightsRatio','Existing shares required for one new share',4,1,10,1],
 ['rightsDiscount','Subscription discount to the entered old share price (%)',40,0,100,5],
 ['rightsCash','Outside cash available for the subscription (CAD)',150,0,100000,50]
]}};
export function rightsCashBenchmark(i,discount=i.rightsDiscount,ratio=i.rightsRatio){
 const subscriptionPrice=i.rightsOldPrice*(1-discount/100),theoreticalPrice=discount===0?i.rightsOldPrice:(ratio*i.rightsOldPrice+subscriptionPrice)/(ratio+1);
 const newUnits=i.rightsUnits/ratio,subscriptionCash=newUnits*subscriptionPrice,oldValue=i.rightsUnits*i.rightsOldPrice,oldAfter=i.rightsUnits*theoreticalPrice;
 const entitlementValue=Math.max(0,oldValue-oldAfter),beforeResources=oldValue+i.rightsCash,shortfall=Math.max(0,subscriptionCash-i.rightsCash),funded=i.rightsCash>=subscriptionCash;
 return {subscriptionPrice,theoreticalPrice,newUnits,subscriptionCash,oldValue,oldAfter,entitlementValue,beforeResources,shortfall,funded,
  exerciseResources:funded?(i.rightsUnits+newUnits)*theoreticalPrice+i.rightsCash-subscriptionCash:null,
  sellResources:oldAfter+i.rightsCash+entitlementValue,lapseResources:oldAfter+i.rightsCash};
}
export function rightsCashResult(kind,i){
 if(kind!=='rightsCash')throw Error('Unknown rights-cash topic.');
 const p=rightsCashBenchmark(i);
 const alternatives=[{label:'Before detachment · shares plus cash',value:p.beforeResources}];
 if(p.funded)alternatives.push({label:'Exercise · funded theoretical benchmark',value:p.exerciseResources});
 alternatives.push({label:'Sell all rights · theoretical price',value:p.sellResources},{label:'Let rights lapse · no compensation',value:p.lapseResources});
 return {metrics:[['Cash required to subscribe to the full entitlement',p.subscriptionCash,'money'],['Theoretical value of the holding’s rights',p.entitlementValue,'money'],['Additional outside cash required before subscribing',p.shortfall,'money']],note:'An independently authored, fully subscribed, pro-rata rights-issue benchmark; no company, security quote or actual offer is evaluated. The offer grants one new share per selected number of old shares. Subscription price is the entered old quote less its selected percentage discount. Existing business value is assumed unchanged; new subscription cash adds value dollar for dollar and all company new shares are ultimately taken up, regardless of this holder’s choice. The theoretical ex-rights price is (ratio × old quote + subscription price) / (ratio + 1), not a forecast of trading price. The eligible holding’s entitlement is calculated proportionally, including mathematical fractional new shares with no rounding or dealing restriction. Rights are assumed transferable and sold at the calculated theoretical value without fees in the sale scenario. Lapse receives no compensation. Neither term applies universally to actual offers. No issue fee, tax, spread, price movement, deadline date, receipt delay, interest, corporate-value change or tax cost basis is calculated. The outside cash is the only funding available to exercise; no asset sale or borrowing is invented. '+(p.funded?'The entered cash covers the modeled full subscription.':'The exercise-resource row is omitted because the entered cash does not cover the modeled full subscription.')+' Resource totals include the same opening shares and outside cash in every displayed alternative. They are static theoretical comparisons, not guaranteed executable transactions, income or a judgment about whether participation is suitable.',charts:[
  {id:'rights-cash-price-bases',type:'bar',axisRight:36,title:'A subscription discount is measured against a price before rights detach',unit:'money',unitLabel:'Hypothetical CAD per share · distinct price bases',rows:[{label:'Old share price · rights still attached',value:i.rightsOldPrice},{label:'Subscription price per new share',value:p.subscriptionPrice},{label:'Theoretical ex-rights share price',value:p.theoreticalPrice}],note:'The new shares and enlarged company are priced together in this benchmark. Dividing the old quote by the lower subscription price and calling the difference a promised return would ignore both the entitlement and the theoretical price adjustment. Actual trading prices can differ from every benchmark assumption.'},
  {id:'rights-cash-entitlement-bridge',type:'waterfall',title:'Reconcile the old holding’s theoretical repricing with the rights it receives',unit:'money',unitLabel:'CAD value of old shares plus their rights · outside cash excluded',rows:[{label:'Old shares with entitlement attached',value:p.oldValue},{label:'Theoretical repricing of old shares',value:p.oldAfter-p.oldValue},{label:'Separate theoretical rights entitlement',value:p.entitlementValue}],totalLabel:'Old shares plus rights · theoretical value',note:'The entitlement restores the old holding’s value in this unchanged-business benchmark. It is a separate right with a conditional use, not free extra profit layered on top of an unchanged old share price. No right is sold and no cash receipt is generated by this valuation bridge.'},
  {id:'rights-cash-resource-alternatives',type:'bar',axisRight:36,title:'Compare complete resources while keeping subscription funding visible',unit:'money',unitLabel:'Hypothetical CAD · investment value plus remaining outside cash',rows:alternatives,note:'Exercise, when fully funded, converts outside cash into new shares. The sale scenario keeps the old shares and receives the theoretical rights value. Both preserve the same total resources under these assumptions. Lapse forfeits the rights without proceeds. The exercise row is absent if available cash is insufficient; the funding-gap metric reports what is missing. This is not an automatic liquidation, financing arrangement or instruction to act.'},
  {id:'rights-cash-discount-ratio-grid',type:'heatmap',title:'Test how the discount and entitlement ratio change the value at stake',unit:'money',unitLabel:'Theoretical CAD value of this existing holding’s rights',columns:['1 : 2','1 : 4','1 : 5','1 : 10'],rows:[0,20,40,60].map(discount=>({label:discount+'% off',values:[2,4,5,10].map(ratio=>rightsCashBenchmark(i,discount,ratio).entitlementValue)})),note:'Columns mean one new share per the stated number of old shares; rows replace the discount to the old quote. Only existing eligible shares and the old quote remain selected for the entitlement-value calculation. These are theoretical values before any fee or market-price change, not cash required to subscribe or returns guaranteed by an offer.'}
 ]};
}
